css:
:scope { width: min(100%, 1189px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 14 / span 10; grid-row: 1 / span 69; aspect-ratio: 506 / 549; }
.gx__i2 { grid-column: 1 / span 12; grid-row: 8 / span 3; font-family: var(--os-font-label); font-size: 14px; font-weight: 500; line-height: 1.5; letter-spacing: 0.39em; text-transform: uppercase; color: var(--os-color-heading); }
.gx__i3 { grid-column: 1 / span 12; grid-row: 16 / span 13; font-family: var(--os-font-heading); font-size: 54px; font-weight: 400; line-height: 0.98; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 11; grid-row: 35 / span 14; font-family: var(--os-font-heading); font-size: 17px; font-weight: 400; line-height: 1.29; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 1 / span 6; grid-row: 55 / span 6; font-family: var(--os-font-body); font-size: 12px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-transform: uppercase; color: inherit; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i2 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 43px; }
  .gx__i4 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 14px; }
}
